export default {"P000017":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000017</code></p><h3>Affine</h3><p>For every affine open V of Y, <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>f</mi><mrow><mo>−</mo><mn>1</mn></mrow></msup><mo stretchy=\"false\">(</mo><mi>V</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">f^{-1}(V)</annotation></semantics></math></span></span> is affine.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01S5\">Stacks 01S5 · affine morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01S5\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=47\">M. Hoyois, Algebraic Geometry, 23 September 2026, Proposition 4.36(i), the affine base-change test</a> · <a href=\"https://stacks.math.columbia.edu/tag/01S6\">Stacks 01S6 · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01S6\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000017\">Open shared record</a></p></article>","P000031":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000031</code></p><h3>Affine</h3><p>Isomorphic to <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">\\operatorname{Spec} A</annotation></semantics></math></span></span> for a ring A.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01II\">Stacks 01II · schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01II\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=12\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 2.20, affine schemes in the functor-of-points description</a> · <a href=\"https://stacks.math.columbia.edu/tag/01HW\">Stacks 01HW · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01HW\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000031\">Open shared record</a></p></article>","P000064":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000064</code></p><h3>Clopen basis (point-set zero dimensionality)</h3><p>The topology has a basis of subsets that are both open and closed. This condition by itself imposes no separation axiom.</p><p class=\"property-references\"><a href=\"https://doi.org/10.1017/9781316543870\">Dickmann–Schwartz–Tressl, Spectral Spaces</a></p><p class=\"algebra-links\"><a href=\"../database/#P000064\">Open shared record</a></p></article>","P000016":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000016</code></p><h3>Cohen–Macaulay</h3><p>Locally Noetherian, with depth equal to Krull dimension at each local ring.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/02IN\">Stacks 02IN · Cohen–Macaulay schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-02IN\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000016\">Open shared record</a></p></article>","P000029":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000029</code></p><h3>Connected</h3><p>The underlying space is nonempty and admits no partition into two nonempty disjoint opens.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004S\">Stacks 004S · connected spaces and their components</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004S\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000029\">Open shared record</a></p></article>","P000060":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000060</code></p><h3>Connected space (Pi-Base convention)</h3><p>There is no cover by two disjoint nonempty open subsets. The empty space satisfies this predicate.</p><p class=\"property-references\"><a href=\"https://topology.pi-base.org/properties/P000036\">Pi-Base connectedness</a> · <a href=\"https://stacks.math.columbia.edu/tag/004S\">Stacks 004S · comparison with the nonempty convention</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004S\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000060\">Open shared record</a></p></article>","P000003":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000003</code></p><h3>Étale</h3><p>Smooth of relative dimension zero; equivalently flat, unramified and locally of finite presentation.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/02GH\">Stacks 02GH · étale morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-02GH\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_3\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Definition 18.34 and Theorem 18.44, including local finite presentation</a> · <a href=\"https://stacks.math.columbia.edu/tag/02GI\">Stacks 02GI · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-02GI\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000003\">Open shared record</a></p></article>","P000069":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000069</code></p><h3>Every irreducible component has nonempty interior</h3><p>For each maximal nonempty irreducible closed subset, its interior in the ambient space is nonempty.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004V\">Stacks 004V · source for the predicate</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004V\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000069\">Open shared record</a></p></article>","P000065":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000065</code></p><h3>Extremally disconnected space</h3><p>The closure of every open subset is open. The property is stronger than a clopen basis among profinite spaces, and is not the same as total disconnectedness.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08YH\">Stacks 08YH · extremally disconnected spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YH\">Index</a> · <a href=\"https://doi.org/10.1017/9781316543870\">Dickmann–Schwartz–Tressl, Spectral Spaces</a></p><p class=\"algebra-links\"><a href=\"../database/#P000065\">Open shared record</a></p></article>","P000019":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000019</code></p><h3>Finite</h3><p>Affine, with every corresponding coordinate algebra finite as a module over the base ring.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01WG\">Stacks 01WG · finite and integral morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01WG\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01WH\">Stacks 01WH · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01WH\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000019\">Open shared record</a></p></article>","P000068":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000068</code></p><h3>Finitely many irreducible components</h3><p>The set of maximal nonempty irreducible closed subsets of the space is finite.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004V\">Stacks 004V · source for the predicate</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004V\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000068\">Open shared record</a></p></article>","P000006":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000006</code></p><h3>Flat</h3><p>For a morphism <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi><mo>:</mo><mi>X</mi><mo>→</mo><mi>Y</mi></mrow><annotation encoding=\"application/x-tex\">f:X\\to Y</annotation></semantics></math></span></span> and every <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi><mo>∈</mo><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">x\\in X</annotation></semantics></math></span></span>, the stalk <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi class=\"math-euler-script\" mathvariant=\"normal\">𝒪</mi><mrow><mi>X</mi><mo separator=\"true\">,</mo><mi>x</mi></mrow></msub></mrow><annotation encoding=\"application/x-tex\">\\mathcal O_{X,x}</annotation></semantics></math></span></span> is flat as an <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi class=\"math-euler-script\" mathvariant=\"normal\">𝒪</mi><mrow><mi>Y</mi><mo separator=\"true\">,</mo><mi>f</mi><mo stretchy=\"false\">(</mo><mi>x</mi><mo stretchy=\"false\">)</mo></mrow></msub></mrow><annotation encoding=\"application/x-tex\">\\mathcal O_{Y,f(x)}</annotation></semantics></math></span></span>-module. On affine charts this is equivalent to exactness of extension of scalars along the coordinate ring map.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01U2\">Stacks 01U2 · flat morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01U2\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-30733-2_15\">U. Görtz and T. Wedhorn, Algebraic Geometry I, second edition, Definition 14.1(1),(3), stalks of the structure sheaf</a> · <a href=\"https://stacks.math.columbia.edu/tag/01U3\">Stacks 01U3 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01U3\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000006\">Open shared record</a></p></article>","P000039":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000039</code></p><h3>Flat ∧ locally finitely presented</h3><p>Both flatness and local finite presentation hold for the same morphism.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01UA\">Stacks 01UA · flat morphisms locally of finite presentation are universally open</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01UA\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000039\">Open shared record</a></p></article>","P000015":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000015</code></p><h3>Gorenstein</h3><p>Locally Noetherian, with each local ring of finite injective dimension as a module over itself.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0AWV\">Stacks 0AWV · Gorenstein schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/duality/#tag-0AWV\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_10\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Definition 25.123, the stalk criterion for a locally Noetherian scheme</a> · <a href=\"https://stacks.math.columbia.edu/tag/0AWW\">Stacks 0AWW · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/duality/#tag-0AWW\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000015\">Open shared record</a></p></article>","P000053":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000053</code></p><h3>Hausdorff space</h3><p>Distinct points have disjoint open neighbourhoods.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08ZY\">Stacks 08ZY · characterization of profinite spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08ZY\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000053\">Open shared record</a></p></article>","P000049":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000049</code></p><h3>Hausdorff underlying space</h3><p>Any two distinct points have disjoint Zariski-open neighbourhoods.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0CKV\">Stacks 0CKV · zero-dimensional schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-0CKV\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/08YF\">Stacks 08YF · spectral spaces and the constructible topology</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YF\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000049\">Open shared record</a></p></article>","P000061":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000061</code></p><h3>Hyperconnected space</h3><p>Any two nonempty open subsets intersect. This includes the empty space; irreducibility of schemes adds nonemptiness.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004U\">Stacks 004U · irreducible spaces and generic points</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004U\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000061\">Open shared record</a></p></article>","P000037":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · compound · <code>P000037</code></p><h3>Integral</h3><p>A scheme is integral when it is nonempty and every nonempty affine open has an integral domain as its coordinate ring. Equivalently it is reduced and irreducible.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01OK\">Stacks 01OK · affine-local definition of an integral scheme · Stacks 01OK · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OK\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01OJ\">Stacks 01OJ · integral schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OJ\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=80\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 8.43 and Example 8.44</a></p><p class=\"algebra-links\"><a href=\"../database/#P000037\">Open shared record</a></p></article>","P000045":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000045</code></p><h3>Integral morphism</h3><p>Affine, and integral on coordinate rings (every element satisfies a monic polynomial over the base).</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01WG\">Stacks 01WG · finite and integral morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01WG\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01WH\">Stacks 01WH · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01WH\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000045\">Open shared record</a></p></article>","P000028":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000028</code></p><h3>Irreducible</h3><p>The space is nonempty and every two nonempty opens intersect. Equivalently it is nonempty and cannot be written as a union of two proper closed subsets.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/004V\">Stacks 004V · irreducible spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004V\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01OM\">Stacks 01OM · irreducible schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OM\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000028\">Open shared record</a></p></article>","P000048":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000048</code></p><h3>Krull dimension at most zero</h3><p>Every point of the underlying space is closed. Equivalently, no affine chart has a strict inclusion of prime ideals. This convention includes the empty scheme.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0CKV\">Stacks 0CKV · zero-dimensional schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-0CKV\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000048\">Open shared record</a></p></article>","P000030":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000030</code></p><h3>Local</h3><p>A local scheme is <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">\\operatorname{Spec} A</annotation></semantics></math></span></span> for a local ring A. Equivalently, it has a unique closed point to which every point specializes.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01II\">Stacks 01II · schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01II\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000030\">Open shared record</a></p></article>","P000008":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000008</code></p><h3>Local complete intersection</h3><p>At every source point the morphism is of finite type and has a neighbourhood on which it factors as a Koszul-regular immersion followed by a smooth morphism.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/069F\">Stacks 069F · local complete intersection morphisms · Stacks 069F · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/more-morphisms/#tag-069F\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_4\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Definitions 19.10 and 19.37, Koszul regularity in the local factorization</a></p><p class=\"algebra-links\"><a href=\"../database/#P000008\">Open shared record</a></p></article>","P000014":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000014</code></p><h3>Local complete intersection</h3><p>Locally Noetherian, with each local ring having completion isomorphic to a quotient of a regular local ring by a regular sequence.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/09Q9\">Stacks 09Q9 · complete intersection homomorphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/dpa/#tag-09Q9\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/0AWV\">Stacks 0AWV · Gorenstein schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/duality/#tag-0AWV\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_4\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Proposition 19.49(1), completion of a Noetherian local ring</a></p><p class=\"algebra-links\"><a href=\"../database/#P000014\">Open shared record</a></p></article>","P000010":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000010</code></p><h3>Locally connected</h3><p>Every point has a basis of connected open neighbourhoods.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/04MD\">Stacks 04MD · local connectedness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-04MD\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/004S\">Stacks 004S · connected spaces and their components</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-004S\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000010\">Open shared record</a></p></article>","P000062":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000062</code></p><h3>Locally connected space</h3><p>Connected open subsets form a basis of the topology.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/04MD\">Stacks 04MD · definition of local connectedness</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-04MD\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000062\">Open shared record</a></p></article>","P000009":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000009</code></p><h3>Locally Noetherian</h3><p>Has an affine open covering with Noetherian coordinate rings. Requiring just Noetherian stalks is insufficient.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01OU\">Stacks 01OU · Noetherian schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OU\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=78\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 8.26</a> · <a href=\"https://stacks.math.columbia.edu/tag/01OV\">Stacks 01OV · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OV\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000009\">Open shared record</a></p></article>","P000067":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000067</code></p><h3>Locally Noetherian space</h3><p>Every point has a neighbourhood whose subspace topology is Noetherian. The neighbourhood is required to contain an open neighbourhood of the point.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0051\">Stacks 0051 · source for the predicate · Stacks 0051 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-0051\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000067\">Open shared record</a></p></article>","P000001":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000001</code></p><h3>Locally of finite presentation</h3><p>On affine charts the coordinate algebra is finitely presented over the target ring.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01TO\">Stacks 01TO · morphisms of finite presentation</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01TO\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000001\">Open shared record</a></p></article>","P000002":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000002</code></p><h3>Locally of finite type</h3><p>On affine charts the coordinate algebra is finitely generated over the target ring.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01T0\">Stacks 01T0 · morphisms of finite type</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01T0\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000002\">Open shared record</a></p></article>","P000071":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Algebraic spaces · predicate · <code>P000071</code></p><h3>Locally separated algebraic space</h3><p>Take the absolute diagonal <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi>X</mi></msub><mo>:</mo><mi>X</mi><mo>→</mo><mi>X</mi><msub><mo>×</mo><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi mathvariant=\"normal\">𝐙</mi></mrow></msub><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta_X:X\\to X\\times_{\\operatorname{Spec}\\mathbf Z} X</annotation></semantics></math></span></span>. It is an immersion.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/03BS\">Stacks 03BS · source for the predicate · Stacks 03BS · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/spaces-properties/#tag-03BS\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000071\">Open shared record</a></p></article>","P000036":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · compound · <code>P000036</code></p><h3>Noetherian</h3><p>Has a finite open affine cover by spectra of Noetherian rings.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01OU\">Stacks 01OU · Noetherian schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OU\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=78\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 8.26</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=69\">M. Hoyois, Algebraic Geometry, 23 September 2026, Proposition 7.37, finite affine subcovers</a> · <a href=\"https://stacks.math.columbia.edu/tag/01OV\">Stacks 01OV · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OV\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000036\">Open shared record</a></p></article>","P000063":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000063</code></p><h3>Noetherian topological space</h3><p>The descending chain condition holds for closed subsets. Equivalently, every subspace is quasi-compact: the ascending chain condition on opens is equivalent to finite generation of their open unions.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0050\">Stacks 0050 · Noetherian topological spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-0050\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/0059\">Stacks 0059 · quasi-compact spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-0059\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/0051\">Stacks 0051 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-0051\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000063\">Open shared record</a></p></article>","P000066":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000066</code></p><h3>Noetherian underlying space</h3><p>The Zariski space is Noetherian as a topological space. This condition alone does not require any affine coordinate ring to be Noetherian.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01OZ\">Stacks 01OZ · Noetherian schemes have Noetherian spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01OZ\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/0050\">Stacks 0050 · Noetherian topological spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-0050\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000066\">Open shared record</a></p></article>","P000012":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000012</code></p><h3>Normal</h3><p>Every local ring is an integrally closed domain. This definition does not assume the scheme locally Noetherian.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/033H\">Stacks 033H · normal schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-033H\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000012\">Open shared record</a></p></article>","P000027":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000027</code></p><h3>Of finite presentation</h3><p>Locally of finite presentation, quasi-compact and quasi-separated.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01TO\">Stacks 01TO · morphisms of finite presentation</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01TO\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000027\">Open shared record</a></p></article>","P000026":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000026</code></p><h3>Of finite type</h3><p>Locally of finite type and quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01T0\">Stacks 01T0 · morphisms of finite type</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01T0\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000026\">Open shared record</a></p></article>","P000055":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000055</code></p><h3>Profinite space</h3><p>A cofiltered inverse limit of finite discrete spaces. Equivalently, quasi-compact, Hausdorff and totally disconnected.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08ZY\">Stacks 08ZY · characterization of profinite spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08ZY\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000055\">Open shared record</a></p></article>","P000050":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000050</code></p><h3>Profinite underlying space</h3><p>The underlying Zariski space is a cofiltered inverse limit of finite discrete spaces.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0CKV\">Stacks 0CKV · zero-dimensional schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-0CKV\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/08ZY\">Stacks 08ZY · characterization of profinite spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08ZY\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000050\">Open shared record</a></p></article>","P000020":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000020</code></p><h3>Projective</h3><p>Isomorphic over <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y</mi></mrow><annotation encoding=\"application/x-tex\">Y</annotation></semantics></math></span></span> to a closed subscheme of a projective bundle <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">ℙ</mi><mi>Y</mi></msub><mo stretchy=\"false\">(</mo><mi class=\"math-euler-script\" mathvariant=\"normal\">ℰ</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\mathbb P_Y(\\mathcal E)</annotation></semantics></math></span></span> for a quasi-coherent <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi class=\"math-euler-script\" mathvariant=\"normal\">𝒪</mi><mi>Y</mi></msub></mrow><annotation encoding=\"application/x-tex\">\\mathcal O_Y</annotation></semantics></math></span></span>-module <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi class=\"math-euler-script\" mathvariant=\"normal\">ℰ</mi></mrow><annotation encoding=\"application/x-tex\">\\mathcal E</annotation></semantics></math></span></span> of finite type.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01W7\">Stacks 01W7 · projective morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01W7\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01W8\">Stacks 01W8 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01W8\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000020\">Open shared record</a></p></article>","P000023":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000023</code></p><h3>Proper</h3><p>Separated, of finite type and universally closed.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01W0\">Stacks 01W0 · proper morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01W0\">Index</a> · <a href=\"https://link.springer.com/content/pdf/10.1007/978-3-658-30733-2_13.pdf#page=25\">Görtz &amp; Wedhorn, Algebraic Geometry I: Schemes, 2nd ed., Definition 12.55, p. 348. Properness requires finite type, separatedness and universal closedness.</a> · <a href=\"https://stacks.math.columbia.edu/tag/01W1\">Stacks 01W1 · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01W1\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000023\">Open shared record</a></p></article>","P000047":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · compound · <code>P000047</code></p><h3>Qcqs morphism</h3><p>The morphism and its diagonal are quasi-compact. Equivalently, the morphism is quasi-compact and quasi-separated.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01K2\">Stacks 01K2 · quasi-compact schemes and morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01K2\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · quasi-separated schemes and morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000047\">Open shared record</a></p></article>","P000046":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · compound · <code>P000046</code></p><h3>Qcqs scheme</h3><p>The scheme is quasi-compact and quasi-separated. Equivalently, it has a finite affine open cover and intersections of affine opens are quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01K2\">Stacks 01K2 · quasi-compact schemes and morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01K2\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · quasi-separated schemes and morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/094L\">Stacks 094L · the space of a qcqs scheme is spectral</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-094L\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=69\">M. Hoyois, Algebraic Geometry, 23 September 2026, Propositions 7.37–7.38 and Remark 7.40</a></p><p class=\"algebra-links\"><a href=\"../database/#P000046\">Open shared record</a></p></article>","P000018":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000018</code></p><h3>Quasi-affine</h3><p>A quasi-compact morphism for which each affine open of Y has quasi-affine inverse image. Equivalently, a quasi-compact open immersion into a scheme affine over Y.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01SM\">Stacks 01SM · quasi-affine morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01SM\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01SK\">Stacks 01SK · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01SK\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000018\">Open shared record</a></p></article>","P000032":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000032</code></p><h3>Quasi-affine</h3><p>A quasi-compact scheme admitting an open immersion into an affine scheme.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01P5\">Stacks 01P5 · quasi-affine schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01P5\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=20\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 2.63, an open defined by finitely many principal opens</a> · <a href=\"https://stacks.math.columbia.edu/tag/01P6\">Stacks 01P6 · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-01P6\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000032\">Open shared record</a></p></article>","P000022":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000022</code></p><h3>Quasi-compact</h3><p>The inverse image of every quasi-compact open is quasi-compact; equivalently test affine opens of Y.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01K3\">Stacks 01K3 · quasi-compact morphisms · Stacks 01K3 · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01K3\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=69\">M. Hoyois, Algebraic Geometry, 23 September 2026, Proposition 7.39, inverse images of affine opens</a></p><p class=\"algebra-links\"><a href=\"../database/#P000022\">Open shared record</a></p></article>","P000033":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000033</code></p><h3>Quasi-compact</h3><p>Every open covering admits a finite subcover, with no separation axiom implied.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01K3\">Stacks 01K3 · quasi-compact morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01K3\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=69\">M. Hoyois, Algebraic Geometry, 23 September 2026, Proposition 7.37, finite subcovers of an affine cover</a></p><p class=\"algebra-links\"><a href=\"../database/#P000033\">Open shared record</a></p></article>","P000074":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Algebraic spaces · predicate · <code>P000074</code></p><h3>Quasi-compact fibre products of affine tests</h3><p>For every pair of morphisms <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U</mi><mo>→</mo><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">U\\to X</annotation></semantics></math></span></span> and <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mo>→</mo><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">V\\to X</annotation></semantics></math></span></span> from affine schemes, the scheme <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U</mi><msub><mo>×</mo><mi>X</mi></msub><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">U\\times_XV</annotation></semantics></math></span></span> is quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0AHR\">Stacks 0AHR · source for the predicate</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/spaces-properties/#tag-0AHR\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000074\">Open shared record</a></p></article>","P000075":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Algebraic spaces · predicate · <code>P000075</code></p><h3>Quasi-compact fibre products of quasi-compact tests</h3><p>For every pair of morphisms <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U</mi><mo>→</mo><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">U\\to X</annotation></semantics></math></span></span> and <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mo>→</mo><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">V\\to X</annotation></semantics></math></span></span> from quasi-compact schemes, the scheme <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U</mi><msub><mo>×</mo><mi>X</mi></msub><mi>V</mi></mrow><annotation encoding=\"application/x-tex\">U\\times_XV</annotation></semantics></math></span></span> is quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0AHR\">Stacks 0AHR · source for the predicate</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/spaces-properties/#tag-0AHR\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000075\">Open shared record</a></p></article>","P000052":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000052</code></p><h3>Quasi-compact space</h3><p>Every open cover admits a finite subcover.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0059\">Stacks 0059 · quasi-compact spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-0059\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000052\">Open shared record</a></p></article>","P000021":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000021</code></p><h3>Quasi-projective</h3><p>Of finite type and admitting a relatively ample invertible sheaf, in the Stacks convention. Hoyois Definition 4.35(ii) uses a quasi-compact open immersion into a projective scheme over the base. Over a quasi-compact and quasi-separated base the Stacks criterion gives such a factorization.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01VV\">Stacks 01VV · quasi-projective morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01VV\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/07RM\">Stacks 07RM · projective compactification over a qcqs base</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-07RM\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=47\">Hoyois, Definition 4.35(ii)</a> · <a href=\"https://stacks.math.columbia.edu/tag/01VW\">Stacks 01VW · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01VW\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000021\">Open shared record</a></p></article>","P000025":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000025</code></p><h3>Quasi-separated</h3><p>The diagonal <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi><mo>→</mo><mi>X</mi><msub><mo>×</mo><mi>Y</mi></msub><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X\\to X\\times_Y X</annotation></semantics></math></span></span> is quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · separation axioms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-30733-2_11\">U. Görtz and T. Wedhorn, Algebraic Geometry I, second edition, Definition 10.22, quasi-compact diagonal</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KK\">Stacks 01KK · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KK\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000025\">Open shared record</a></p></article>","P000035":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000035</code></p><h3>Quasi-separated</h3><p>Intersections of any two affine opens are quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · separation axioms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-30733-2_8\">U. Görtz and T. Wedhorn, Algebraic Geometry I, second edition, Definition 7.21, intersections of affine opens</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=69\">M. Hoyois, Algebraic Geometry, 23 September 2026, Proposition 7.38</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KK\">Stacks 01KK · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KK\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000035\">Open shared record</a></p></article>","P000072":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Algebraic spaces · predicate · <code>P000072</code></p><h3>Quasi-separated algebraic space</h3><p>Take the absolute diagonal <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi>X</mi></msub><mo>:</mo><mi>X</mi><mo>→</mo><mi>X</mi><msub><mo>×</mo><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi mathvariant=\"normal\">𝐙</mi></mrow></msub><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta_X:X\\to X\\times_{\\operatorname{Spec}\\mathbf Z} X</annotation></semantics></math></span></span>. It is quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/03BS\">Stacks 03BS · source for the predicate · Stacks 03BS · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/spaces-properties/#tag-03BS\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000072\">Open shared record</a></p></article>","P000013":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000013</code></p><h3>Reduced</h3><p>All stalks have zero nilradical; equivalently every affine coordinate ring is reduced.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01IZ\">Stacks 01IZ · reduced schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01IZ\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=77\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 8.13 and Proposition 8.15, affine-local criterion</a> · <a href=\"https://stacks.math.columbia.edu/tag/01J0\">Stacks 01J0 · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01J0\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000013\">Open shared record</a></p></article>","P000011":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000011</code></p><h3>Regular</h3><p>Locally Noetherian and every local ring is regular: its dimension equals the minimal number of generators of its maximal ideal.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/02IR\">Stacks 02IR · regular schemes</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-02IR\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000011\">Open shared record</a></p></article>","P000024":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000024</code></p><h3>Separated</h3><p>The diagonal <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi><mo>→</mo><mi>X</mi><msub><mo>×</mo><mi>Y</mi></msub><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">X\\to X\\times_Y X</annotation></semantics></math></span></span> is a closed immersion.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · separation axioms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-30733-2_10\">U. Görtz and T. Wedhorn, Algebraic Geometry I, second edition, Definition and Proposition 9.7(i), diagonal criterion</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=67\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 7.25</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KK\">Stacks 01KK · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KK\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000024\">Open shared record</a></p></article>","P000034":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000034</code></p><h3>Separated</h3><p>Separated over <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi mathvariant=\"normal\">ℤ</mi></mrow><annotation encoding=\"application/x-tex\">\\operatorname{Spec}\\mathbb Z</annotation></semantics></math></span></span>; the diagonal into the product over <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi mathvariant=\"normal\">ℤ</mi></mrow><annotation encoding=\"application/x-tex\">\\operatorname{Spec}\\mathbb Z</annotation></semantics></math></span></span> is closed.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · separation axioms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=67\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 7.25 applied over Spec ℤ</a> · <a href=\"https://doi.org/10.1007/978-3-658-30733-2_10\">U. Görtz and T. Wedhorn, Algebraic Geometry I, second edition, Definition and Proposition 9.7(i), diagonal criterion</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KK\">Stacks 01KK · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KK\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000034\">Open shared record</a></p></article>","P000070":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Algebraic spaces · predicate · <code>P000070</code></p><h3>Separated algebraic space</h3><p>Take the absolute diagonal <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Δ</mi><mi>X</mi></msub><mo>:</mo><mi>X</mi><mo>→</mo><mi>X</mi><msub><mo>×</mo><mrow><mi mathvariant=\"normal\">Spec</mi><mo>⁡</mo><mi mathvariant=\"normal\">𝐙</mi></mrow></msub><mi>X</mi></mrow><annotation encoding=\"application/x-tex\">\\Delta_X:X\\to X\\times_{\\operatorname{Spec}\\mathbf Z} X</annotation></semantics></math></span></span>. It is a closed immersion.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/03BS\">Stacks 03BS · source for the predicate · Stacks 03BS · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/spaces-properties/#tag-03BS\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000070\">Open shared record</a></p></article>","P000004":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000004</code></p><h3>Smooth</h3><p>Locally of finite presentation, flat, with geometrically regular fibres.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01V4\">Stacks 01V4 · smooth morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01V4\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_3\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Corollary 18.57(i),(iv), geometrically regular fibres</a> · <a href=\"https://stacks.math.columbia.edu/tag/01V5\">Stacks 01V5 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01V5\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000004\">Open shared record</a></p></article>","P000058":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000058</code></p><h3>Sober space</h3><p>Every nonempty irreducible closed subset has a unique generic point.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08YF\">Stacks 08YF · spectral spaces and the constructible topology</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YF\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000058\">Open shared record</a></p></article>","P000038":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000038</code></p><h3>Spectral</h3><p>Quasi-compact, sober, with a basis of quasi-compact opens stable under finite intersection. A scheme has spectral underlying space exactly when it is quasi-compact and quasi-separated.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08YF\">Stacks 08YF · spectral spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YF\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KH\">Stacks 01KH · separation axioms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KH\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000038\">Open shared record</a></p></article>","P000056":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000056</code></p><h3>Spectral space</h3><p>A sober, quasi-compact space with a basis of quasi-compact opens and with their pairwise intersections quasi-compact.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08YF\">Stacks 08YF · spectral spaces and the constructible topology</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YF\">Index</a> · <a href=\"https://api.pageplace.de/preview/DT0400.9781108609586_A36703407/preview-9781108609586_A36703407.pdf#page=24\">Dickmann, Schwartz &amp; Tressl, Spectral Spaces, Definition 1.1.5. The four spectral axioms include unique generic points for nonempty irreducible closed sets.</a> · <a href=\"https://stacks.math.columbia.edu/tag/08YG\">Stacks 08YG · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YG\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000056\">Open shared record</a></p></article>","P000051":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Schemes · predicate · <code>P000051</code></p><h3>Spectral with profinite patch topology</h3><p>The Zariski space is spectral and its patch topology, generated by quasi-compact opens and their complements, is profinite.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/094L\">Stacks 094L · the space of a qcqs scheme is spectral</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/properties/#tag-094L\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/08YF\">Stacks 08YF · spectral spaces and the constructible topology</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YF\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000051\">Open shared record</a></p></article>","P000043":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000043</code></p><h3>Surjective</h3><p>Every point of the target has a preimage. Surjectivity of schemes is preserved under arbitrary base change.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01RZ\">Stacks 01RZ · surjectivity</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01RZ\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/01S1\">Stacks 01S1 · base change of a surjective morphism</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01S1\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000043\">Open shared record</a></p></article>","P000005":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000005</code></p><h3>Syntomic</h3><p>Flat and locally of finite presentation, with every fibre a local complete intersection over its residue field.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01UC\">Stacks 01UC · syntomic morphisms · Stacks 01UC · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01UC\">Index</a> · <a href=\"https://stacks.math.columbia.edu/tag/00SL\">Stacks 00SL · syntomic ring maps</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/algebra/#tag-00SL\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_4\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Definition 19.51 and Proposition 19.52(i)–(ii), flatness and the fibre criterion</a></p><p class=\"algebra-links\"><a href=\"../database/#P000005\">Open shared record</a></p></article>","P000059":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000059</code></p><h3>T₀ space</h3><p>Distinct points are distinguished by some open subset. Equivalently, distinct points have distinct closures.</p><p class=\"property-references\"><a href=\"https://doi.org/10.1017/9781316543870\">Dickmann–Schwartz–Tressl, Spectral Spaces</a></p><p class=\"algebra-links\"><a href=\"../database/#P000059\">Open shared record</a></p></article>","P000057":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000057</code></p><h3>T₁ space</h3><p>Every singleton is closed.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08YF\">Stacks 08YF · spectral spaces and the constructible topology</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08YF\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000057\">Open shared record</a></p></article>","P000054":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Topological spaces · predicate · <code>P000054</code></p><h3>Totally disconnected space</h3><p>Each nonempty connected component consists of a single point.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/08ZY\">Stacks 08ZY · characterization of profinite spaces</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/topology/#tag-08ZY\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000054\">Open shared record</a></p></article>","P000041":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000041</code></p><h3>Universal homeomorphism</h3><p>Every base change is a homeomorphism on underlying spaces. No isomorphism of structure sheaves is required.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/04DC\">Stacks 04DC · universal homeomorphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-04DC\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=55\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 5.32 and Proposition 5.33(i), after arbitrary base change</a> · <a href=\"https://stacks.math.columbia.edu/tag/04DD\">Stacks 04DD · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-04DD\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000041\">Open shared record</a></p></article>","P000042":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000042</code></p><h3>Universally closed</h3><p>After every base change the map sends closed sets to closed sets.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01W0\">Stacks 01W0 · proper morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01W0\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=55\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 5.32 and Proposition 5.33(i), after arbitrary base change</a> · <a href=\"https://stacks.math.columbia.edu/tag/01KB\">Stacks 01KB · numbered source statement</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/schemes/#tag-01KB\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000042\">Open shared record</a></p></article>","P000044":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000044</code></p><h3>Universally injective</h3><p>Injective after every base change. Equivalently injective on points with purely inseparable residue field extensions.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01S2\">Stacks 01S2 · radicial morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01S2\">Index</a> · <a href=\"https://link.springer.com/content/pdf/10.1007/978-3-658-30733-2_5.pdf#page=17\">Görtz &amp; Wedhorn, Algebraic Geometry I: Schemes, 2nd ed., Proposition 4.35, p. 111. Universal injectivity is equivalent to injectivity on points and purely inseparable extensions of all residue fields.</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=55\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 5.32 and Proposition 5.33(i), after arbitrary base change</a> · <a href=\"https://stacks.math.columbia.edu/tag/01S3\">Stacks 01S3 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01S3\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000044\">Open shared record</a></p></article>","P000040":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000040</code></p><h3>Universally open</h3><p>After every base change the map sends opens to opens.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/01UA\">Stacks 01UA · flat morphisms locally of finite presentation are universally open</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01UA\">Index</a> · <a href=\"https://hoyois.app.uni-regensburg.de/SS26/alggeo2/script.pdf#page=55\">M. Hoyois, Algebraic Geometry, 23 September 2026, Definition 5.32 and Proposition 5.33(i), after arbitrary base change</a> · <a href=\"https://stacks.math.columbia.edu/tag/01U0\">Stacks 01U0 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-01U0\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000040\">Open shared record</a></p></article>","P000007":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Morphisms of schemes · predicate · <code>P000007</code></p><h3>Unramified</h3><p>Locally of finite type with zero relative differentials. Equivalently, the diagonal is an open immersion and the map is locally of finite type.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/02G3\">Stacks 02G3 · unramified morphisms</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-02G3\">Index</a> · <a href=\"https://doi.org/10.1007/978-3-658-43031-3_3\">U. Görtz and T. Wedhorn, Algebraic Geometry II, Definition 18.22 and Proposition 18.29(i)–(iii), assuming local finite type</a> · <a href=\"https://stacks.math.columbia.edu/tag/02G4\">Stacks 02G4 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/morphisms/#tag-02G4\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000007\">Open shared record</a></p></article>","P000073":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Algebraic spaces · predicate · <code>P000073</code></p><h3>Zariski locally quasi-separated algebraic space</h3><p>There is a Zariski open cover by quasi-separated algebraic spaces.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/03BS\">Stacks 03BS · source for the predicate · Stacks 03BS · common source definition</a> <a class=\"algebra-index-ref\" href=\"../database/stacks/spaces-properties/#tag-03BS\">Index</a></p><p class=\"algebra-links\"><a href=\"../database/#P000073\">Open shared record</a></p></article>"};
